-- Before: row-by-row cursor (40 minutes)
DECLARE @ProductID INT, @Rate DECIMAL(5,4);
DECLARE cur CURSOR FOR
    SELECT p.ProductID FROM Production.Product p;
OPEN cur;
FETCH NEXT FROM cur INTO @ProductID;
WHILE @@FETCH_STATUS = 0
BEGIN
    SELECT @Rate = r.IncreaseRate
    FROM dbo.CategoryRates r
    JOIN Production.Product p ON p.ProductSubcategoryID = r.SubcategoryID
    WHERE p.ProductID = @ProductID;

    UPDATE Production.Product
    SET ListPrice = ListPrice * (1 + ISNULL(@Rate, 0))
    WHERE ProductID = @ProductID;

    FETCH NEXT FROM cur INTO @ProductID;
END
CLOSE cur; DEALLOCATE cur;

-- After: single set-based UPDATE
UPDATE p
SET p.ListPrice = p.ListPrice * (1 + ISNULL(r.IncreaseRate, 0))
FROM Production.Product AS p
LEFT JOIN dbo.CategoryRates AS r ON r.SubcategoryID = p.ProductSubcategoryID;

