from airflow.decorators import dag, task
from datetime import datetime


@dag(schedule="@daily", start_date=datetime(2026, 1, 1), catchup=False)
def nightly_file_processing():

    @task
    def list_staged_files() -> list[str]:
        # real listing logic (e.g. S3/ADLS/stage listing) goes here
        return ["file_01.csv", "file_02.csv", "file_03.csv"]

    @task
    def process_file(filename: str) -> dict:
        print(f"Processing {filename}")
        return {"filename": filename, "status": "ok"}

    @task
    def summarize(results: list[dict]):
        ok_count = sum(1 for r in results if r["status"] == "ok")
        print(f"{ok_count}/{len(results)} files processed successfully")

    files = list_staged_files()
    results = process_file.expand(filename=files)
    summarize(results)


nightly_file_processing()

