# modules/landing-storage/variables.tf
variable "environment" {
  type = string
  validation {
    condition     = contains(["dev", "staging", "prod"], var.environment)
    error_message = "environment must be dev, staging, or prod."
  }
}
variable "location" {
  type    = string
  default = "eastus2"
}

# modules/landing-storage/main.tf
locals {
  replication_by_env = {
    dev     = "LRS"
    staging = "LRS"
    prod    = "GRS"
  }
}

resource "azurerm_storage_account" "landing" {
  name                     = "st${var.environment}landing001"
  resource_group_name      = var.resource_group_name
  location                 = var.location
  account_tier             = "Standard"
  account_replication_type = local.replication_by_env[var.environment]

  tags = {
    environment = var.environment
    managed_by  = "terraform"
    purpose     = "pipeline-landing-zone"
  }
}

# modules/landing-storage/outputs.tf
output "storage_account_name" {
  value = azurerm_storage_account.landing.name
}

# envs/prod/main.tf -- calling the module per environment
module "landing_storage" {
  source              = "../../modules/landing-storage"
  environment         = "prod"
  resource_group_name  = azurerm_resource_group.prod.name
}

